SELECT s.id AS submissionId, s.user_id AS userId, s.question_id AS questionId, q.title AS questionTitle, u.username AS username, s.status AS status, s.score AS score, s.time_used_ms AS timeUsedMs, s.sql_content AS sqlContent, s.created_at AS createdAt FROM `db_submission` s LEFT JOIN `db_question` q ON q.id = s.question_id LEFT JOIN `user` u ON u.id = s.user_id
s.user_id = #{userId} AND s.question_id = #{questionId} AND s.status = #{status} AND q.created_by = #{createdBy}
ORDER BY s.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM `db_submission` s
LEFT JOIN `db_question` q ON q.id = s.question_id

    s.user_id = #{userId}
    AND s.question_id = #{questionId}
    AND s.status = #{status}
    AND q.created_by = #{createdBy}

SELECT * FROM `db_submission`
WHERE contest_id = #{contestId}
ORDER BY id ASC

